use vstd::prelude::*;

verus! {
    /// Returns a new byte array containing a contiguous subsequence of a given byte array.
    /// The subsequence starts at a specified starting position and has a specified length.
    fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8>
        requires
            count == 0 || (offset < buffer.len() && offset + count <= buffer.len()),
        ensures
            result.len() == count,
            forall|i: usize| 0 <= i < count ==> result[i] == buffer[offset + i],
    {
        let mut result: Vec<u8> = Vec::new();
        let mut i: usize = 0;

        // Initialize the result vector with the specified count
        while i < count
            invariant
                0 <= i <= count,
                result.len() == i,
                forall|j: usize| 0 <= j < i ==> result[j] == buffer[offset + j],
                offset + i <= buffer.len(),
            decreases count - i,
        {
            result.push(buffer[offset + i]);
            i = i + 1;
        }

        result
    }
}
